#!/usr/bin/env node
// Generates the web client's part catalog from content/parts.json.
// The client bundles a byte-faithful copy of the server content document so the
// offline slope builder and the palette render exactly what the server serves;
// this generator keeps the copy in lockstep instead of hand-maintaining a table.
//
// Usage:
//   node tools/web-parts/generate-play-parts.mjs          # write the generated files
//   node tools/web-parts/generate-play-parts.mjs --check  # exit 1 if stale, write nothing

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(HERE, "..", "..");
const SOURCE = join(REPO, "content", "parts.json");
const TEXTURES = join(REPO, "clients", "web", "public", "assets", "original", "part-textures.json");
const OUT_DIR = join(REPO, "clients", "web", "src", "builder");
const CHECK = process.argv.includes("--check");

/**
 * Build-mode alignment bounds of each part's bracket, in whole world units relative to the
 * part origin. A glider wing's collider sits half a cell left of the frame its four connection
 * points belong to, so aligning on the collider plants the wing half a cell into its neighbour;
 * the frame is what the player lines up (see ADR-018). Taken from the original's `frame`
 * condition sprites, which is the same art the build overlay draws.
 */
function bracketBoxes() {
  if (!existsSync(TEXTURES)) {
    console.error(`texture manifest not found: ${TEXTURES}`);
    process.exit(1);
  }

  const textures = JSON.parse(readFileSync(TEXTURES, "utf8")).parts;
  const boxes = [];
  for (const [partTypeId, texture] of Object.entries(textures)) {
    const frames = (texture.sprites ?? []).filter((sprite) => sprite.condition?.kind === "frame");
    if (frames.length === 0) {
      continue;
    }

    let x0 = Number.POSITIVE_INFINITY;
    let x1 = Number.NEGATIVE_INFINITY;
    let y0 = Number.POSITIVE_INFINITY;
    let y1 = Number.NEGATIVE_INFINITY;
    for (const frame of frames) {
      x0 = Math.min(x0, frame.cx - frame.sx / 2);
      x1 = Math.max(x1, frame.cx + frame.sx / 2);
      y0 = Math.min(y0, frame.cy - frame.sy / 2);
      y1 = Math.max(y1, frame.cy + frame.sy / 2);
    }

    const round = (value) => Number(value.toFixed(4));
    boxes.push({
      partTypeId: Number(partTypeId),
      halfX: round((x1 - x0) / 2),
      halfY: round((y1 - y0) / 2),
      offsetX: round((x0 + x1) / 2),
      offsetY: round((y0 + y1) / 2),
    });
  }

  boxes.sort((left, right) => left.partTypeId - right.partTypeId);
  return boxes;
}

if (!existsSync(SOURCE)) {
  console.error(`content document not found: ${SOURCE}`);
  process.exit(1);
}

const document = JSON.parse(readFileSync(SOURCE, "utf8"));
if (!Array.isArray(document.parts)) {
  console.error(`${SOURCE} has no parts array.`);
  process.exit(1);
}

const outputs = [
  {
    path: join(OUT_DIR, "playParts.generated.json"),
    content: `${JSON.stringify(document, null, 2)}\n`,
  },
  {
    path: join(OUT_DIR, "playParts.generated.ts"),
    content: `// Generated by tools/web-parts/generate-play-parts.mjs — do not edit by hand.
import document from "./playParts.generated.json";
import type { PartContentDocument } from "@/schema/types";
export const PLAY_PARTS = document as unknown as PartContentDocument;
`,
  },
  {
    path: join(OUT_DIR, "frameBoxes.generated.json"),
    content: `${JSON.stringify(
      { format: "pigforge.part-frame-boxes", schemaVersion: 1, boxes: bracketBoxes() },
      null,
      2,
    )}\n`,
  },
  {
    path: join(OUT_DIR, "frameBoxes.generated.ts"),
    content: `// Generated by tools/web-parts/generate-play-parts.mjs — do not edit by hand.
import type { PartFrameBox } from "@/schema/types";
import document from "./frameBoxes.generated.json";
const boxes = document as unknown as { boxes: PartFrameBox[] };
/** Build-mode alignment bounds of each part's bracket, from the original's \`frame\` sprites. */
export const PART_FRAME_BOXES: ReadonlyMap<number, PartFrameBox> = new Map(
  boxes.boxes.map((box) => [box.partTypeId, box]),
);
`,
  },
];

if (CHECK) {
  const stale = outputs.filter(
    (output) => !existsSync(output.path) || readFileSync(output.path, "utf8") !== output.content,
  );
  if (stale.length > 0) {
    for (const output of stale) {
      console.error(`stale: ${relative(REPO, output.path)}`);
    }
    console.error("run: node tools/web-parts/generate-play-parts.mjs");
    process.exit(1);
  }
} else {
  for (const output of outputs) {
    writeFileSync(output.path, output.content);
  }
}

console.log(`parts: ${document.parts.length}`);
